-- Table structure for table `sys_payment`
--

DROP TABLE IF EXISTS `sys_payment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_payment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_image` longblob,
  `id_card_image` longblob,
  `created` datetime DEFAULT NULL,
  `updated` datetime DEFAULT NULL,
  `statu` int(11) NOT NULL DEFAULT '1',
  `user_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pay_user_id` (`user_id`),
  CONSTRAINT `pay_user_id` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

